INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2014 - Year in Review', 'اقتصاد اليمن 2014 - مراجعة السنة', 'The year 2014 was defined by a rapid deterioration of Yemen''s political and security environment, culminating in the Houthi takeover of the capital, Sanaa, in September, which effectively marked the beginning of the current civil war. Economically, the country faced severe challenges, including a substantial decline in oil revenue due to the sabotage of oil facilities and the government''s controversial elimination of fuel subsidies under pressure from the IMF. This instability resulted in a real GDP contraction of -3.9% and contributed to a humanitarian crisis that saw 10.5 million people food insecure and over 334,000 internally displaced persons by the end of the year.', 'The year 2014 was defined by a rapid deterioration of Yemen''s political and security environment, culminating in the Houthi takeover of the capital, Sanaa, in September, which effectively marked the beginning of the current civil war. Economically, the country faced severe challenges, including a substantial decline in oil revenue due to the sabotage of oil facilities and the government''s controversial elimination of fuel subsidies under pressure from the IMF. This instability resulted in a real GDP contraction of -3.9% and contributed to a humanitarian crisis that saw 10.5 million people food insecure and over 334,000 internally displaced persons by the end of the year.', '2014-12-31', 'economic', 'high', 'IMF, World Bank, UN OCHA, Trading Economics, Index Mundi, Exchange Rates UK, Crisis Group', 'year-2014,annual-review');

