INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2018 - Year in Review', 'اقتصاد اليمن 2018 - مراجعة السنة', 'The year 2018 was defined by a severe humanitarian crisis and significant economic and political events. The Saudi-led coalition deposited **$2 billion** into the Central Bank of Yemen (CBY) in March, which temporarily stabilized the Yemeni Rial and curbed hyperinflation. However, the conflict escalated dramatically with the start of the **Battle of Hodeidah** in June, threatening the country''s main port and humanitarian lifeline. The year concluded with the **Stockholm Agreement** in December, which established a ceasefire in Hodeidah and provided a fragile political breakthrough. The overall economic situation remained dire, with a small positive GDP growth of **0.8%** following years of contraction, and inflation remaining high at **33.65%**.', 'The year 2018 was defined by a severe humanitarian crisis and significant economic and political events. The Saudi-led coalition deposited **$2 billion** into the Central Bank of Yemen (CBY) in March, which temporarily stabilized the Yemeni Rial and curbed hyperinflation. However, the conflict escalated dramatically with the start of the **Battle of Hodeidah** in June, threatening the country''s main port and humanitarian lifeline. The year concluded with the **Stockholm Agreement** in December, which established a ceasefire in Hodeidah and provided a fragile political breakthrough. The overall economic situation remained dire, with a small positive GDP growth of **0.8%** following years of contraction, and inflation remaining high at **33.65%**.', '2018-12-31', 'economic', 'high', 'World Bank, Exchange-Rates.org, Statista, UN OCHA FTS, IPC, UNHCR, Saudi Ministry of Finance, Al Jazeera, ACAPS', 'year-2018,annual-review');

