INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2020 - Year in Review', 'اقتصاد اليمن 2020 - مراجعة السنة', 'The year 2020 was marked by a severe economic contraction, with preliminary estimates suggesting an 8.5% shrinkage in GDP, primarily driven by the compounding effects of the ongoing conflict, economic fragmentation, and the global COVID-19 pandemic. The conflict continued with a major Houthi offensive on Marib, while the economic divide deepened with a significant divergence between the nominal official exchange rate of 250 YER/USD and the parallel market rate, which averaged around 772 YER/USD in Aden. The humanitarian crisis intensified, with 16.2 million people facing food insecurity and the total stock of internally displaced persons (IDPs) reaching 4 million since 2015, all while the $3.38 billion humanitarian appeal was only 58.9% funded. Fiscal policy remained constrained, with the Internationally Recognized Government relying on money printing to cover expenditures due to underperforming public revenue and slow oil production recovery.', 'The year 2020 was marked by a severe economic contraction, with preliminary estimates suggesting an 8.5% shrinkage in GDP, primarily driven by the compounding effects of the ongoing conflict, economic fragmentation, and the global COVID-19 pandemic. The conflict continued with a major Houthi offensive on Marib, while the economic divide deepened with a significant divergence between the nominal official exchange rate of 250 YER/USD and the parallel market rate, which averaged around 772 YER/USD in Aden. The humanitarian crisis intensified, with 16.2 million people facing food insecurity and the total stock of internally displaced persons (IDPs) reaching 4 million since 2015, all while the $3.38 billion humanitarian appeal was only 58.9% funded. Fiscal policy remained constrained, with the Internationally Recognized Government relying on money printing to cover expenditures due to underperforming public revenue and slow oil production recovery.', '2020-12-31', 'economic', 'high', 'World Bank, IMF, Statista, ReliefWeb, UN OCHA, IOM, Human Rights Watch, PMC, EU Factsheet', 'year-2020,annual-review');

