INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2021 - Year in Review', 'اقتصاد اليمن 2021 - مراجعة السنة', 'The year 2021 was marked by a severe economic and humanitarian crisis, driven by the Houthi offensive on the strategic, oil-rich Marib governorate and a crippling fuel crisis. Macroeconomic fragmentation intensified, leading to the Yemeni Rial''s collapse in the IRG-controlled south, with the parallel market rate exceeding 1,700 YER/USD by December, fueling an estimated 45% inflation rate. The humanitarian situation remained the world''s worst, with 20.7 million people in need of aid and the IDP population reaching 4.3 million, while the UN''s $3.85 billion response plan remained significantly underfunded.', 'The year 2021 was marked by a severe economic and humanitarian crisis, driven by the Houthi offensive on the strategic, oil-rich Marib governorate and a crippling fuel crisis. Macroeconomic fragmentation intensified, leading to the Yemeni Rial''s collapse in the IRG-controlled south, with the parallel market rate exceeding 1,700 YER/USD by December, fueling an estimated 45% inflation rate. The humanitarian situation remained the world''s worst, with 20.7 million people in need of aid and the IDP population reaching 4.3 million, while the UN''s $3.85 billion response plan remained significantly underfunded.', '2021-12-31', 'economic', 'high', 'IMF DataMapper, FEWS NET, World Bank, UN OCHA, UNHCR, UN OCHA FTS, Sana''a Center, ACAPS', 'year-2021,annual-review');

