VALUES ('Fiscal Fragmentation (Dual Central Banks)', 'Fiscal Fragmentation (Dual Central Banks)', 'Fiscal Fragmentation (Dual Central Banks) led to Widely Divergent Exchange Rates. Sana''a vs. Aden, 560 vs. 1200 YER/USD', 'Fiscal Fragmentation (Dual Central Banks) led to Widely Divergent Exchange Rates. Sana''a vs. Aden, 560 vs. 1200 YER/USD', '2022-06-30', 'political', 'medium', 'World Bank, IMF, UN OCHA, FEWS, ACAPS, Wikipedia', 'year-2022,causation');

INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2023 - Year in Review', 'اقتصاد اليمن 2023 - مراجعة السنة', 'The year 2023 was defined by a fragile de-escalation driven by Saudi-Houthi talks, yet the economic and humanitarian crises deepened due to severe fiscal fragmentation. The Houthi-imposed blockade on oil exports caused a significant decline in the Internationally Recognized Government''s (IRG) revenues, exacerbating the banking crisis and leading to a stark divergence in inflation and exchange rates between IRG and Houthi-controlled areas. Real GDP contracted by an estimated 2.0%, while 21.6 million people remained in need of humanitarian assistance, underscoring the severe impact of the protracted conflict and economic warfare on the civilian population.', 'The year 2023 was defined by a fragile de-escalation driven by Saudi-Houthi talks, yet the economic and humanitarian crises deepened due to severe fiscal fragmentation. The Houthi-imposed blockade on oil exports caused a significant decline in the Internationally Recognized Government''s (IRG) revenues, exacerbating the banking crisis and leading to a stark divergence in inflation and exchange rates between IRG and Houthi-controlled areas. Real GDP contracted by an estimated 2.0%, while 21.6 million people remained in need of humanitarian assistance, underscoring the severe impact of the protracted conflict and economic warfare on the civilian population.', '2023-12-31', 'economic', 'high', 'IMF DataMapper, World Bank, UN OCHA, IOM, Sana''a Center for Strategic Studies, Crisis Group, Statista, Central Bank of Yemen (CBY)', 'year-2023,annual-review');

