INSERT INTO events (titleEn, titleAr, descriptionEn, descriptionAr, date, category, impactLevel, sources, tags)
VALUES ('Yemen Economy 2024 - Year in Review', 'اقتصاد اليمن 2024 - مراجعة السنة', 'The year 2024 was defined by the significant escalation of the **Red Sea crisis**, where the Houthi movement''s attacks on international shipping lanes led to retaliatory military strikes by a US-led coalition, effectively freezing the fragile peace process. Economically, the country continued to suffer from a fragmented fiscal system and a sustained blockade on oil exports, resulting in a projected **GDP contraction of 1.0%** and an estimated **inflation rate of 27%**. The humanitarian crisis remained catastrophic, with **18.2 million people** requiring assistance and the Humanitarian Response Plan facing a massive **$2.7 billion funding gap**, further exacerbating acute food insecurity for over 17 million people.', 'The year 2024 was defined by the significant escalation of the **Red Sea crisis**, where the Houthi movement''s attacks on international shipping lanes led to retaliatory military strikes by a US-led coalition, effectively freezing the fragile peace process. Economically, the country continued to suffer from a fragmented fiscal system and a sustained blockade on oil exports, resulting in a projected **GDP contraction of 1.0%** and an estimated **inflation rate of 27%**. The humanitarian crisis remained catastrophic, with **18.2 million people** requiring assistance and the Humanitarian Response Plan facing a massive **$2.7 billion funding gap**, further exacerbating acute food insecurity for over 17 million people.', '2024-12-31', 'economic', 'high', 'World Bank, UN OCHA, IMF, Central Bank of Yemen (CBY), CSIS, Atlas Institute, Security Council Report, Human Rights Watch', 'year-2024,annual-review');

